function plot_IqaAmpHistory( moduleNumber )
% function plot_IqaAmpHistory( moduleNumber )
% plot_IqaIqHistory.m - File used to plot the fast history buffer files
%               for an IQA module generated by setting, for example,
%               SRF1:STN:IQA1:MODU.GAHS to 1
%               lcaPut('SRF1:STN:IQA1:MODU.GAHS', 1)
%               SRF1:STN:IQA2:MODU.GAHS to 1
%               lcaPut('SRF1:STN:IQA2:MODU.GAHS', 1)
%               SRF1:STN:IQA3:MODU.GAHS to 1
%               lcaPut('SRF1:STN:IQA3:MODU.GAHS', 1)
%               to save data from IQA module 1, 2, or 3
%               Each of the above files is saved in the file
%               /zantar/epicsdata/app/spear/data/SRF1/iqaNAmpHistory.dat
%               overwriting any earlier file
%               This function is based on the plot_IQAn.m functions
%               written for the RFfaultfiles gui
% moduleNumber  number of IQA module
% program currently works for 2 or 3, need to modify for 1 in the future

% use existing functions in RFtoolbox for compatibility
stationName = 'SRF1';
machine = stationtomachine( stationName );
prm = sys_prm(machine);

rfFrequency =  prm.accel.wrf / (2 * pi);
harmonicNumber =  prm.accel.h;
samplesPerRev =  prm.rf.hcomb;
rfData = prm.files.rf_data;

rfFrequencyMHz = rfFrequency/1e6;

% set hObject to empty matrix
hObject = [];
handles = struct( 'output', hObject, ...  % pointer to figure window 
    'rfData', rfData, ...                 % directory that contains the files 
    'station',stationName, ...                 % rf station under investigation 
    'idAction', 1, ...                    % id of plotting routine 
    'labAction', 'RFP Cavity', ...        % label of plotting command 
    'fftFlag', 0, ...                     % yes/no flag to calculate fft  
    'samplingFrequency', (rfFrequencyMHz*samplesPerRev)/harmonicNumber,...% Module sampling frequency in MHz.
    'Tsample', 1/((samplesPerRev*rfFrequency)/harmonicNumber), ...               % sample period for one revolution 
    'nTurns', inf, ...                    % number of turns to plot 
    'figHandles', [], ...                 % number of figures that are plotted 
    'fftFigHandles',[], ...               % number of figures that plot FFTs 
    'maxTime',[], ...                     % Vector of maximum time per plot
    'time', [], ...                       % time vector (abscissa) of data 
    'data', [], ...                          % matrix of data (ordinate) to plot 
    'faultNumber', '1' );                  % fault file number to plot.

format compact

station = handles.station;
rf_data = handles.rfData;

% default file name
fName = sprintf('iqa%dAmpHistory.dat', moduleNumber);
% fName = sprintf('iqa%dIqHistory.dat', moduleNumber);
u_header = fullfile(rf_data, station);
fileName = fullfile(u_header, fName);
Tsample = handles.Tsample;

% define channel names for each mux setting
cavity = ['A'; 'B'; 'C'; 'D'];
channelName = {
    sprintf('Cavity %c Forward', cavity(2*(moduleNumber-2) + 1))
    sprintf('Cavity %c Reflected', cavity(2*(moduleNumber-2) + 1 ))
    sprintf('Cavity %c Forward', cavity(2*(moduleNumber-2) + 2))
    sprintf('Cavity %c Reflected', cavity(2*(moduleNumber-2) + 2 ))
    sprintf('Cavity %c Probe', cavity(2*(moduleNumber-2) + 1))
    sprintf('Cavity %c Probe', cavity(2*(moduleNumber-2) + 2))
    sprintf('Waveguide %d Load Forward', moduleNumber)
    sprintf('Waveguide %d Load Reflected', moduleNumber)
    };

% define the database strings for each mux setting
dbString = {
    sprintf(':CAV%1dFRWD:', 2*(moduleNumber-2) + 1) 
    sprintf(':CAV%1dREFL:', 2*(moduleNumber-2) + 1) 
    sprintf(':CAV%1dFRWD:', 2*(moduleNumber-2) + 2) 
    sprintf(':CAV%1dREFL:', 2*(moduleNumber-2) + 2) 
    sprintf(':CAV%1dPROBE:', 2*(moduleNumber-2) + 1) 
    sprintf(':CAV%1dPROBE:', 2*(moduleNumber-2) + 1)
    sprintf(':WG%02dLDFRWD:', moduleNumber)
    sprintf(':WG%02dLDREFL:', moduleNumber)
    };

% see if file exists and, if it does, get the file creation date
dStruct = dir(fileName);
if isempty(dStruct),
    fprintf(1, 'file %s does not exist\n', fileName);
    return
end % if isempty(dStruct),
datetime = dStruct.date;
% get the file ID
fid1 = -1;
fid1 = fopen(fileName,'r','ieee-be');
if fid1 == -1
   fprintf(1,'Error - cannot open %s\n', fileName);
   return
end % if fid1 == -1

% read the fault file to find channel name
% first read 1 word to determine what channel the mux was set to
fprintf(1,'Reading IQA multiplexer setting from file\n');
[header1,count]  = fread(fid1,[1,21],'char');	% read the header string
% get current file position
dataStart = ftell(fid1);
[mux_data_compare,count] = fread(fid1,[1],'uint16'); %Used to see if its 8 ch. mode.
[mux_data,count] = fread(fid1,[1],'uint16'); % fclose(fid1); % read one word
mux_data_compare = bitand(mux_data_compare,7) + 1;
mux_data = bitand(mux_data,7) + 1;	% zero the top 13 bits and add one

% reposition file to start of data
seekStatus = fseek(fid1, dataStart, 'bof');
if (seekStatus == -1),
    fprintf(1, 'unable to reposition %s to position %d\n', ...
        fileName, dataStart);
    fclose(fid1);
    return
end % if (seekStatus == -1),
[data,count1] = fread(fid1,[1,inf],'uint16'); fclose(fid1);

% make the time vector
timeVector = linspace(0,Tsample*count1,count1);	% time vector

% scale the data
% IQA module amplitudes use bits 15:4 of the 15:0 word
% we will divide down the data to ignore bits 3:0
% create matrix of data indices from last 4 bits of data
dataInd = bitand(data, 7) + 1;
dataInd = fliplr(dataInd);
data = (fix((data-32768)/16))/2048;	% ignore lower 4 bits & scale for full scale = 1
data = fliplr(data);	% arrange from old to new data
dataLength = length(data);

% check for version number of IQA module
pvVersion = sprintf('SRF1:STN:IQA%d:MODU.VERN', moduleNumber);
IQAVern = lcaGet(pvVersion);
% if IQA3vern (version number) is 4371 and mux_data for two consecutive
% data points are different then loop through mux_data.
eightChFlag = 0;
if ( (IQAVern == 4371) && (mux_data ~= mux_data_compare ) )
   eightChFlag = 1;
   mux_data = 1;
end

% get scale factors
coupling_dB = lcaGet(strcat(station, strcat(dbString, 'IQ:SCALE.A')));
cable_loss_dB = lcaGet(strcat(station, strcat(dbString, 'IQ:SCALE.B')));
fudge_factor_dB = lcaGet(strcat(station, strcat(dbString, 'IQ:SCALE.F')));
ampl_conv_dB = lcaGet(strcat(station, strcat(dbString, 'A:SCALE.C')));
% calcuate the total channel conversion loss in dB
total_dB = coupling_dB + cable_loss_dB + fudge_factor_dB + ampl_conv_dB;

% convert to voltage scale factor
voltage_scaling = 10.^(total_dB/20);

if (~eightChFlag),
    out_data = data;
    time = timeVector;
    figInd=0;
    figInd=figInd+1;figure(figInd);clf;
    % scale data appropriately
    if ((mux_data == 5) || (mux_data == 6)),
        outData = ...
            ((abs(out_data)*voltage_scaling(mux_data)*2))/(1e3);
        yLabelStr = 'voltage (kV)';
    else
        outData = ...
            ((abs(out_data)*voltage_scaling(mux_data)*2).^2)/(100*1e3);
        yLabelStr = 'power (kW)';
    end % if ((mux_data == 5) || (mux_data == 6)),
    plot(time/1e-3, abs(outData))
    grid on
    title(sprintf('IQA Module %1d Fault File - %s  %s  %s', ...
        moduleNumber, station, channelName{mux_data}, datetime))
    xlabel('time - (ms)')
    ylabel(yLabelStr)
    return
end % if (eightChFlag),

% everything else is eight channel case
% sort data for eight channel case
% find first index of channel 1
stInd = find((dataInd == 1), 1);
% truncate data to multiple of eight
dataLength = 8*floor((dataLength-stInd+1)/8);
% reshape data
out_data = reshape(data(stInd-1+(1:dataLength)), 8, round(dataLength/8));
time = timeVector(1:8:dataLength);

% allocate space
outData = zeros(size(out_data));

% % calcuate the total channel conversion loss in dB
% total_dB = coupling_dB + cable_loss_dB + fudge_factor_dB + ampl_conv_dB;
% 
% % convert to voltage scale factor
% voltage_scaling = 10.^(total_dB/20);

% calculate the power in kW
for ind = [1:4 7:8],
    outData(ind,:) = ...
        ((abs(out_data(ind,:))*voltage_scaling(ind)*2).^2)/(100*1e3);
end % for ind = [1:4 7:8],
for ind = 5:6,
    outData(ind,:) = ...
        ((abs(out_data(ind,:))*voltage_scaling(ind)*2))/(1e3);
end % for ind = 5:6,
% omit fft plots for now
%      % Plot FFT of out_data if fftFlag is set on faultFile gui.
%      % retrieve figure data
%      fftFigHandles = handles.fftFigHandles;
%      if handles.fftFlag == 1
%
%        % increment to the next FFT figure
%        fftFigInd=length(fftFigHandles)+20;       %offset fftFigInd by 20 to separate FFT figs.
%        fftFigInd=fftFigInd+1; figure(fftFigInd); clf; fftFigHandles(fftFigInd-20) = fftFigInd;
%
%        %Calculate FFT
%        theData = out_data;
%        N = length(theData);          %Number of theData points
%        df = handles.samplingFrequency/N;                    %Resolution frequency
%        f = [0:df:handles.samplingFrequency - df];           %Analysis frequencies
%
%        theData = theData - mean(theData); %subtract DC component.
%        theDATA = abs(fft(theData))/(N/2);
%        semilogy(f(1:N/2),theDATA(1:N/2));  %Other half of FFT is mirror image.
%        xlabel('Frequency (MHz)');
%        ylabel('Amplitude');
%        title(['FFT of IQA Module #3 Fault File - ',station,' ',channel_name,' ',datetime] );
%    end %if handles.fftFlag == 'yes'

%    if (eightChFlag)
%       mux_data = mux_data + 1;  %If 8 channel mode, increment to next mux_data.
%    else
%       mux_data = 9; % sets mux_data to 9 in single channel mode to exit loop.
%    end
%
%    handles.fftFigHandles = fftFigHandles;
% end % while(mux_data < =8 )
% fprintf(1,'Plotting IQA2 Fault File...')
% increment to the next figure

% figHandles = handles.figHandles;
% figInd=length(figHandles);

legendCellStr = {sprintf('Cavity %c', cavity(2*(moduleNumber-2) + 1)); ...
    sprintf('Cavity %c', cavity(2*(moduleNumber-2) + 2))
    };
figInd=0;
figInd=figInd+1; figure(figInd); clf;% figHandles(figInd) = figInd;
% handles.figHandles = figHandles;
% plot the time domain response
subplot(2,1,1)
plot(time/1e-3,abs(outData(1,:)),time/1e-3,abs(outData(3,:)) )
legend(legendCellStr,0)
grid on
title(sprintf('IQA Module %1d Fault File - %s Cavity Forward  %s', ...
    moduleNumber, station, datetime))
xlabel('time - ms')
ylabel('power - kW')
% handles.FigHandles = figHandles;

subplot(2,1,2)
plot(time/1e-3,abs(outData(2,:)),time/1e-3,abs(outData(4,:)) )
legend(legendCellStr,0)
grid on
title(sprintf('IQA Module %1d Fault File - %s Cavity Reflected  %s', ...
    moduleNumber, station, datetime))
xlabel('time - ms')
ylabel('power - kW')

% increment to the next figure
% figHandles = handles.figHandles;
% figInd=length(figHandles);
figInd=figInd+1; figure(figInd); clf; % figHandles(figInd) = figInd;
% handles.figHandles = figHandles;
% plot the time domain response
plot(time/1e-3,abs(outData(5,:)),time/1e-3,abs(outData(6,:)) )
legend(legendCellStr,0)
grid on
title(sprintf('IQA Module %1d Fault File - %s Cavity Probe  %s', ...
    moduleNumber, station, datetime))
xlabel('time - ms')
ylabel('gap voltage - kV')
% handles.FigHandles = figHandles;

% increment to the next figure
% figHandles = handles.figHandles;
% figInd=length(figHandles);
figInd=figInd+1; figure(figInd); clf; % figHandles(figInd) = figInd;
% handles.figHandles = figHandles;
% plot the time domain response
plot(time/1e-3,abs(outData(7,:)),time/1e-3,abs(outData(8,:)) )
legend({'Forward','Reflected'},0)
grid on
title(sprintf('IQA Module %1d Fault File - %s Waveguide %d Load  %s', ...
    moduleNumber, station, moduleNumber, datetime))
% title(['IQA Module #3 Fault File - ',station,' Waveguide 3 Load ',datetime])
xlabel('time - ms')
ylabel('power - kW')
% handles.FigHandles = figHandles;

return
end